type Options struct {
	Version string
	Env     EntireEnv
	Stdout  io.Writer
	Stderr  io.Writer
	// Stdin is where `explain` reads a failing build's output from. It is the only command that takes
	// piped input, because it is the only one whose question ("what are these names the build is
	// complaining about") is asked by composing with another command rather than by naming a symbol.
	Stdin io.Reader
}

func Execute(version string, args []string) error {
	return Run(context.Background(), Options{
		Version: version,
		Env:     EnvFromOS(),
		Stdout:  os.Stdout,
		Stderr:  os.Stderr,
		Stdin:   os.Stdin,
	}, args)
}

func Run(ctx context.Context, opts Options, args []string) error {
	if opts.Version == "" {
		opts.Version = "dev"
	}
	if opts.Stdout == nil {
		opts.Stdout = io.Discard
	}
	if opts.Stderr == nil {
		opts.Stderr = io.Discard
	}

	if len(args) == 0 {
		printHelp(opts.Stdout)
		return nil
	}

	// Per-command help: `entire graph <cmd> --help` prints that command's detail
	// view and exits, without touching each runX. Only fires for commands that
	// have a doc entry — which includes `help` itself, so `help --help` prints
	// help's own detail view rather than the root listing. A bare `--help` has
	// no command word and is handled above.
	if doc, ok := findCommandDoc(args[0]); ok && wantsHelp(doc, args[1:]) {
		renderCommandHelp(opts.Stdout, args[0])
		return nil
	}

	switch args[0] {
	case "diff":
		return runDiff(ctx, opts, args[1:])
	case "commit":
		return runCommit(ctx, opts, args[1:])
	case "checkpoint":
		return runCheckpoint(ctx, opts, args[1:])
	case "analyze":
		return runAnalyze(ctx, opts, args[1:])
	case "doctor":
		return runDoctor(ctx, opts, args[1:])
	case "capabilities":
		return runCapabilities(opts, args[1:])
	case "snapshot":
		return runProviderRecords(ctx, opts, args[1:], "snapshot")
	case "snapshot-query":
		return runSnapshotQuery(opts, args[1:])
	case "symbols":
		return runProviderRecords(ctx, opts, args[1:], "symbols")
	case "edges":
		return runProviderRecords(ctx, opts, args[1:], "edges")
	case "query", "search":
		return runSearch(ctx, opts, args[1:])
	case "index":
		return runIndex(ctx, opts, args[1:])
	case "health":
		return runHealth(ctx, opts, args[1:])
	case "def":
		return runDef(ctx, opts, args[1:])
	case "explain":
		return runExplain(ctx, opts, args[1:])
	case "neighbors":
		return runNeighbors(ctx, opts, args[1:])
	case "impact":
		return runImpact(ctx, opts, args[1:])
	case "verify":
		return runVerify(ctx, opts, args[1:])
	case "stats":
		return runStats(ctx, opts, args[1:])
	case "agent-guide":
		return runAgentGuide(opts, args[1:])
	case "init-agents":
		return runInitAgents(opts, args[1:])
	case "version", "--version", "-v":
		if len(args) > 1 && args[1] == "--json" {
			return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(map[string]string{
				"provider":          sem.ProviderName,
				"version":           opts.Version,
				"identity_revision": sem.IdentityRevision,
			})
		}
		fmt.Fprintln(opts.Stdout, opts.Version)
		return nil
	case "help", "--help", "-h":
		printHelp(opts.Stdout)
		return nil
	default:
		return fmt.Errorf("unknown command %q; run \"entire graph help\" to list commands", args[0])
	}
}

// printHelp renders the grouped root listing. Per-command detail lives in
// renderCommandHelp; both read from the commandDocs registry in help.go.
func printHelp(out io.Writer) {
	renderRootHelp(out)
}

func runDoctor(ctx context.Context, opts Options, args []string) error {
	asJSON := false
	var asserts []string
	for index := 0; index < len(args); index++ {
		switch args[index] {
		case "--json":
			asJSON = true
		case "--assert":
			// Repeatable: a harness usually drives more than one verb, and finding out about the
			// second one only after the first has been fixed costs another whole run.
			if index+1 >= len(args) {
				return errors.New("doctor --assert needs a command line, for example --assert \"search --profile full\"")
			}
			index++
			asserts = append(asserts, args[index])
// wantsHelp reports whether the args request help for the command documented by doc.
//
// It reads the args the way the command's own parser will, because a flat scan for the two spellings
// cannot tell a request for help from DATA that happens to be spelled like one. Two ways it got that
// wrong: `search --query --help` is a search for the literal text "--help" and printed help instead,
// and `diff -- --help` addresses a path named `--help` — after the separator every remaining argument
// is positional by definition, so nothing there can be a flag at all.
//
// The value-taking flags come from the doc registry rather than a second list, because that registry
// is already the thing this file renders and the command parsers are already checked against it
// (agentguide_test.go). A hand-copied list here would be a third spelling of the same fact, and the
// one nothing would notice going stale.
func wantsHelp(doc commandDoc, args []string) bool {
	valued := make(map[string]bool, len(doc.flags))
	for _, flag := range doc.flags {
		if flag.arg != "" {
			valued[flag.name] = true
		}
	}
	for index := 0; index < len(args); index++ {
		switch {
		case args[index] == "--":
			return false
		case valued[args[index]]:
			// The next argument is this flag's VALUE, whatever it is spelled like.
			index++
		case args[index] == "--help" || args[index] == "-h":
			return true
		}
	}
	return false
}

// renderRootHelp prints the grouped, two-column command listing.
func renderRootHelp(w io.Writer) {
	fmt.Fprintln(w, intro)
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Usage:")
	fmt.Fprintln(w, "  entire graph <command> [flags]")

	// Pad command names to a shared width for aligned summaries.
	width := 0
	for _, d := range commandDocs {
		if d.hidden {
			continue
		}
		if len(d.name) > width {
			width = len(d.name)
		}
	}

	for _, g := range groupOrder {
		fmt.Fprintf(w, "\n%s:\n", groupTitles[g])
		for _, d := range commandDocs {
			if d.hidden || d.group != g {
				continue
			}
			fmt.Fprintf(w, "  %-*s   %s\n", width, d.name, d.summary)
		}
	}

	fmt.Fprintln(w, "\nUse \"entire graph <command> --help\" for details on a command.")
	fmt.Fprintln(w, "For coding agents: run \"entire graph agent-guide\" or \"entire graph init-agents\".")
